import { Component } from '@angular/core';
import { FormBuilder, Validators } from '@angular/forms';
import { Router } from '@angular/router';
import { login } from '../Models/login';
import { AuthService } from 'src/app/service/auth.service';
import { CompanyService } from 'src/app/service/company/company.service';
import { JobSeekerService } from 'src/app/service/jobseeker/job-seeker.service';

@Component({
  selector: 'app-login',
  templateUrl: './login.component.html',
  styleUrls: ['./login.component.css']
})
export class LoginComponent {

  constructor(
    private router: Router,
    private fb: FormBuilder,
    private service: AuthService,
    private companyService: CompanyService,
    private jobSeekerService: JobSeekerService
  ) {}

  signup() {
    this.router.navigate(['/register']);
  }

  loginForm = this.fb.group({
    email: ['', [Validators.required, Validators.email]],
    password: ['', [Validators.required, Validators.minLength(6)]]
  });

  onSubmit() {

    if (this.loginForm.invalid) {
      return;
    }

    this.service.login(this.loginForm.value as login).subscribe({

      next: (result: any) => {

        localStorage.setItem("token", result.token);
        localStorage.setItem("role", result.role);
        localStorage.setItem("Id", result.id);

        if (result.role === 'COMPANY') {

          this.companyService.getCompanyById(result.id).subscribe({
            next: (company) => {
              localStorage.setItem("companyName", company.companyName);
              this.router.navigate(['/company-dashboard']);
            }
          });

        } else if (result.role === 'JOBSEEKER') {

          this.jobSeekerService.getJobSeekerById(result.id).subscribe({
            next: (seeker) => {
              localStorage.setItem(
                "userName",
                seeker.firstName + " " + seeker.lastName
              );
              this.router.navigate(['/jobseeker-dashboard']);
            }
          });

        }

        this.loginForm.reset();

      },

      error: (err) => {
        console.error(err);
        alert("Invalid email or password");
      }

    });

  }

}
